export const BODY: string = "\n<p>آپ کے پاس پسندیدہ رنگوں والی تصویر ہے، اور وہ رنگ ویب سائٹ، پوسٹر یا برانڈ کے لیے پیلیٹ کے طور پر چاہییں۔ انہیں آنکھ سے نقل کرنا سست اور غلط ہے۔</p>\n<p>یہ رہنما پانچ مراحل میں تصویر سے رنگ پیلیٹ نکالنا بتاتا ہے: اپ لوڈ کریں، سویچ گنتی چنیں، فیصد پڑھیں اور نتیجہ کاپی یا ڈاؤن لوڈ کریں۔</p>\n<p>ایک بار معلوم ہو جائے تو پورا عمل ایک منٹ سے کم لگتا ہے۔ انسٹال کرنے کو کوئی سافٹ ویئر نہیں، بنانے کو کوئی اکاؤنٹ نہیں، اور کسی سرور پر کوئی فائل اپ لوڈ نہیں ہوتی۔</p>\n<h2 id=\"what-you-need\">شروع کرنے سے پہلے آپ کو کیا چاہیے</h2>\n<p>آپ کو وہ تصویر چاہیے جس میں رنگ ہوں، JPG، PNG یا WebP فارمیٹ میں، 20 MB تک۔ تصویر، مصنوعات کا شاٹ، اسکرین شاٹ یا آرٹ ورک، سب کام کرتے ہیں۔</p>\n<p>جان لیں پیلیٹ کس لیے ہے۔ ویب سائٹ تھیم کو چار سے چھ رنگ چاہییں، برانڈ شناخت کو کچھ زیادہ چاہییں، اور موڈ بورڈ پورے بارہ استعمال کر سکتا ہے۔</p>\n<p>سافٹ ویئر کے طور پر صرف براؤزر چاہیے۔ ٹول کروم، سفاری، فائر فاکس اور ایج پر چلتا ہے، ڈیسک ٹاپ اور موبائل پر، بغیر کسی ایکسٹینشن کے۔</p>\n<h2 id=\"step-1-upload-or-paste\">مرحلہ 1: تصویر اپ لوڈ کریں یا اسکرین شاٹ چسپاں کریں</h2>\n<p><a href=\"/ur/tasveer-se-rang-palette-nikalein/\">تصویر رنگ پیلیٹ ایکسٹریکٹر</a> کھولیں اور اپنی تصویر اپ لوڈ والے حصے میں گھسیٹ دیں۔ آپ اس حصے پر کلک کر کے اپنے آلے سے فائل بھی چن سکتے ہیں۔</p>\n<p>اگر رنگ ابھی آپ کی اسکرین پر ہیں تو اسکرین شاٹ لیں اور Ctrl+V سے چسپاں کریں۔ ٹول کلپ بورڈ تصویریں سیدھی قبول کرتا ہے، اس لیے آپ کسی بھی ویب سائٹ یا ایپ سے پیلیٹ نکال سکتے ہیں۔</p>\n<p>جیسے ہی تصویر لوڈ ہوتی ہے پیلیٹ دکھائی دیتا ہے، پہلے سے طے شدہ 6 سویچ کے ساتھ۔ ہر سویچ اپنا رنگ، اس کے کوڈ اور تصویر کا وہ فیصد دکھاتا ہے جو وہ ڈھکتا ہے۔</p>\n<h2 id=\"step-2-choose-swatch-count\">مرحلہ 2: چنیں کتنے سویچ چاہییں</h2>\n<p>سلائیڈر منتقل کر کے سویچ گنتی 3 سے 12 تک طے کریں۔ ہر بار منتقل کرنے پر پیلیٹ فوراً دوبارہ بنتا ہے، اس لیے آپ سیکنڈوں میں گنتیوں کا موازنہ کر سکتے ہیں۔</p>\n<p>6 سے شروع کریں اور نتیجہ دیکھیں۔ اگر دو سویچ تقریباً ایک جیسے لگیں تو گنتی 4 یا 5 تک کم کریں اور دیکھیں نقل شدہ رنگ ایک صاف رنگ میں مل جاتے ہیں۔</p>\n<p>اگر آپ کی پسند کا ایکسنٹ رنگ گم ہو تو گنتی 12 کی طرف بڑھائیں۔ زیادہ سویچ چھوٹی تفصیل کو اپنا ڈبہ دیتے ہیں، اس لیے چھوٹی نیون سائن یا چھوٹا پھول دکھائی دے سکتا ہے۔</p>\n<h2 id=\"step-3-read-the-percentages\">مرحلہ 3: فیصد اور پٹی پڑھیں</h2>\n<p>ہر سویچ پر فیصد بیج ہوتا ہے جو دکھاتا ہے کہ وہ رنگ تصویر کا کتنا حصہ ڈھکتا ہے۔ سب سے بڑا فیصد غالب رنگ ہے، اور سب سے چھوٹے ایکسنٹ ہیں۔</p>\n<p>فیصد کو اپنے ڈیزائن کی درجہ بندی کے طور پر پڑھیں۔ غالب رنگ کو سب سے زیادہ جگہ ملنی چاہیے، ثانوی رنگ کو معاون کردار، اور سب سے چھوٹے رنگوں کو صرف جھلکیاں۔</p>\n<p>سویچ کے نیچے متناسب رنگ پٹی دیکھیں۔ یہ وہی درجہ بندی بار کے طور پر دکھاتی ہے، حصوں کی چوڑائی فیصد سے میل کھاتی ہے، جس سے توازن کا فیصلہ آسان ہوتا ہے۔</p>\n<h2 id=\"step-4-copy-css-or-json\">مرحلہ 4: پیلیٹ CSS یا JSON کے طور پر کاپی کریں</h2>\n<p>تمام سویچ CSS کسٹم پراپرٹی کے طور پر کاپی کرنے کے لیے Copy CSS پر کلک کریں۔ متغیر ترتیب سے نامزد ہیں، ہر ایک میں HEX قیمت ہے، اور وہ سیدھے اسٹائل شیٹ میں چسپاں ہوتے ہیں۔</p>\n<p>جب پیلیٹ اسٹائل شیٹ کی بجائے کوڈ میں جائے تو Copy JSON پر کلک کریں۔ JSON میں ہر رنگ HEX، RGB اور HSL قیمتیں اور اس کا فیصد حصہ شامل ہیں، ایسی شکل میں جسے اسکرپٹ پڑھ سکتا ہے۔</p>\n<p>سویچ گنتی بدلیں اور برآمدات اپ ڈیٹ ہو جاتی ہیں۔ آپ دوبارہ اپ لوڈ کیے بغیر 6 رنگوں سے 4 پر جا سکتے ہیں، اور کاپی شدہ CSS یا JSON نیا سیٹ فوراً ظاہر کرتا ہے۔</p>\n<h2 id=\"step-5-download-palette-card\">مرحلہ 5: پیلیٹ کارڈ ڈاؤن لوڈ کریں</h2>\n<p>Download Palette PNG پر کلک کر کے پیلیٹ کارڈ بنائیں: اصل تصویر، اس کے نیچے سویچ پٹی اور رنگ۔ یہ نکالنے کا بصری خلاصہ ہے۔</p>\n<p>کارڈ کلائنٹ یا ٹیم کے ساتھ شیئر کریں۔ پیلیٹ کی تصویر HEX کوڈوں کی فہرست سے تیز بات چیت کرتی ہے، خاص طور پر ان لوگوں کے ساتھ جو کوڈ نہیں پڑھتے۔</p>\n<p>کارڈ کو موڈ بورڈ، برانڈ دستاویزات اور پریزنٹیشن میں استعمال کریں۔ یہ دکھاتا ہے کہ رنگ کہاں سے آئے، جو اعتماد بناتا ہے، کیونکہ کلائنٹ ماخذ تصویر دیکھ سکتا ہے۔</p>\n<h2 id=\"extracting-from-a-photo\">تصویر سے پیلیٹ نکالنا</h2>\n<p>تصویریں پیلیٹ کے لیے بہترین ماخذ ہیں، کیونکہ ان کے رنگ حقیقی دنیا میں پہلے سے ایک ساتھ کام کرتے ہیں۔ غروب آفتاب، گلی کا منظر یا مصنوعات کا شاٹ پوری اسکیم دے سکتا ہے۔</p>\n<p>تصویر کے سب سے بڑے چپٹے حصوں سے شروع کریں۔ صاف آسمان، رنگی دیوار یا کپڑے کا ٹکڑا مستحکم رنگ دیتا ہے جسے ایکسٹریکٹر اعلیٰ اور قابل اعتماد درجہ دیتا ہے۔</p>\n<p>ملی جلی روشنی سے ہوشیار رہیں۔ ایک طرف گرم سورج کی روشنی اور دوسری طرف ٹھنڈا سایہ والی تصویر ایک ہی رنگ کے دو ورژن بنا سکتی ہے، جو پیلیٹ میں نقل لگتے ہیں۔</p>\n<h2 id=\"extracting-from-a-logo\">لوگو سے پیلیٹ نکالنا</h2>\n<p>لوگو درست صورت ہے، کیونکہ برانڈ پیلیٹ کو بالکل میل کھانا چاہیے۔ اپنے پاس سب سے اعلیٰ کوالٹی والی لوگو فائل سے شروع کریں، ترجیحاً ٹھوس پس منظر پر PNG۔</p>\n<p>شفاف پس منظر ایکسٹریکٹر سنبھالتا ہے، جو مکمل شفاف پکسل نظرانداز کرتا ہے۔ مگر شفاف پس منظر والا لوگو پھر بھی عجیب نتائج دے سکتا ہے اگر کنارے نیم شفاف ہوں۔</p>\n<p>صاف ترین نتیجے کے لیے پہلے لوگو کو سفید یا برانڈ رنگ والے پس منظر پر رکھیں اور اس ورژن سے نکالیں۔ پیلیٹ پھر لوگو رنگ ظاہر کرتا ہے، شفافیت ہینڈلنگ نہیں۔</p>\n<h2 id=\"extracting-from-a-screenshot\">اسکرین شاٹ سے پیلیٹ نکالنا</h2>\n<p>اسکرین شاٹ کسی ویب سائٹ یا ایپ کی پیلیٹ پکڑنے کا تیز ترین طریقہ ہے جسے آپ پسند کرتے ہیں۔ اسکرین پکڑیں، Ctrl+V سے چسپاں کریں اور پیلیٹ دکھائی دیتا ہے۔</p>\n<p>ایکسٹریکٹر انٹرفیس رنگوں کو کوریج کے حساب سے درجہ دیتا ہے، اس لیے پس منظر اور اہم سطحیں غالب رہتی ہیں، جبکہ بٹن اور لنک رنگ چھوٹے ایکسنٹ کے طور پر دکھائی دیتے ہیں۔</p>\n<p>متن سے محتاط رہیں۔ متن سے بھرا اسکرین شاٹ حروف سے سرمئی اور کالے سویچ بناتا ہے، جو ڈیزائن پیلیٹ کا حصہ نہیں اور نظرانداز کرنے چاہییں۔</p>\n<h2 id=\"when-an-accent-goes-missing\">جب چھوٹا ایکسنٹ گم ہو جائے</h2>\n<p>چھوٹا ایکسنٹ پیلیٹ سے غائب ہو سکتا ہے کیونکہ ایکسٹریکٹر رنگوں کو کوریج کے حساب سے درجہ دیتا ہے۔ تصویر کا 1 فیصد ڈھکنے والی نیون سائن پڑوسی رنگ میں مل سکتی ہے۔</p>\n<p>پہلے سویچ گنتی 12 کی طرف بڑھائیں۔ زیادہ سویچ چھوٹی تفصیل کو اپنا ڈبہ دیتے ہیں، اس لیے ایکسنٹ کے دکھائی دینے کا امکان بہتر ہوتا ہے۔</p>\n<p>اگر وہ پھر بھی نہ دکھائی دے تو اسے آئی ڈراپر سے پکڑیں۔ تصویر رنگ پکر بالکل پکسل پڑھتا ہے، اور آپ وہ رنگ ہاتھ سے نکالے گئے پیلیٹ میں شامل کر سکتے ہیں۔</p>\n<h2 id=\"fixing-duplicate-shades\">پیلیٹ میں نقل شدہ رنگ درست کرنا</h2>\n<p>تقریباً ایک جیسے دکھائی دینے والے دو سویچ عام طور پر گریڈینٹ سے آتے ہیں، جیسے آسمان جو آہستہ ہلکے نیلے سے گہرے نیلے میں بدلتا ہے۔ الگورتھم گریڈینٹ کو دو ڈبوں میں تقسیم کرتا ہے۔</p>\n<p>وہ رنگ رکھیں جو آپ کے ڈیزائن کو بہتر سوٹ کرے اور دوسرا ہٹا دیں۔ ایک نیلے والی پیلیٹ دو نیلوں والی پیلیٹ سے صاف ہے جنہیں کوئی الگ نہیں کر سکتا۔</p>\n<p>متبادل طور پر سویچ گنتی کم کریں۔ 6 رنگوں پر گریڈینٹ عام طور پر ایک ڈبے میں آ جاتا ہے، اور نقل بغیر دستی ترمیم کے غائب ہو جاتی ہے۔</p>\n<h2 id=\"using-the-palette-in-design-tools\">فگما، کینوا اور CSS میں پیلیٹ استعمال کرنا</h2>\n<p>فگما میں ہر HEX کوڈ رنگ سٹائل میں چسپاں کریں۔ فی سویچ ایک سٹائل بنائیں، اس کے کردار کے حساب سے نام دیں، جیسے پس منظر، بنیادی اور ایکسنٹ، تاکہ ٹیم انہیں مستقل استعمال کرے۔</p>\n<p>کینوا میں HEX کوڈ برانڈ کٹ یا ہر عنصر کے رنگ پکر میں چسپاں کریں۔ پیلیٹ پھر اکاؤنٹ کے ہر ڈیزائن میں دستیاب رہتا ہے۔</p>\n<p>CSS میں کاپی شدہ کسٹم پراپرٹی اپنی اسٹائل شیٹ میں چسپاں کریں اور متغیر ہر جگہ حوالہ دیں۔ متغیر پر مبنی پیلیٹ اپ ڈیٹ کرنا آسان ہے، کیونکہ ایک قیمت بدلنے سے پوری سائٹ اپ ڈیٹ ہو جاتی ہے۔</p>\n<h2 id=\"switching-count-without-reupload\">دوبارہ اپ لوڈ کیے بغیر گنتی بدلنا</h2>\n<p>آپ تصویر دوبارہ اپ لوڈ کیے بغیر کسی بھی وقت سویچ گنتی بدل سکتے ہیں۔ سلائیڈر منتقل کریں اور پیلیٹ اسی تصویر ڈیٹا سے فوراً دوبارہ بنتا ہے۔</p>\n<p>یہ گنتیوں کا موازنہ کرنے کے لیے مفید ہے۔ 4، پھر 6، پھر 8 آزمائیں اور دیکھیں پیلیٹ کیسے تفصیل حاصل کرتا ہے اور پھر رنگ نقل کرنا شروع کرتا ہے۔ درست گنتی عام طور پر نقل ظاہر ہونے سے ٹھیک پہلے والی ہے۔</p>\n<p>ہر تبدیلی کے بعد CSS یا JSON کاپی کریں اگر آپ کئی ورژن رکھنا چاہتے ہیں۔ برآمد ہمیشہ موجودہ گنتی ظاہر کرتی ہے، اس لیے پسندیدہ ورژن ضائع ہو سکتا ہے اگر آپ سلائیڈر دوبارہ منتقل کریں۔</p>\n<h2 id=\"extracting-from-product-photos\">مصنوعات کی تصویروں سے پیلیٹ نکالنا</h2>\n<p>مصنوعات کی تصویریں خاص صورت ہیں، کیونکہ پیلیٹ کو مصنوعات کی خدمت کرنی چاہیے، صرف تصویر کی نہیں۔ سفید پس منظر پر مصنوعات کا شاٹ سفید سے غالب پیلیٹ دیتا ہے، جو مصنوعات کے بارے میں کم بتاتا ہے۔</p>\n<p>مصنوعات کے کام کے لیے اسٹوڈیو شاٹ کی بجائے طرز زندگی والے شاٹ سے نکالیں۔ استعمال میں، کمرے یا باہر تصویر شدہ مصنوعات اپنے سیاق کے رنگ رکھتی ہے، اور وہ رنگ بہتر پیلیٹ بناتے ہیں۔</p>\n<p>جب صرف اسٹوڈیو شاٹ موجود ہو تو نکالنے سے پہلے مصنوعات کو تنگ کراپ کریں۔ سفید پس منظر ہٹانے سے ایکسٹریکٹر خالی جگہ کی بجائے مصنوعات کے رنگ درجہ دیتا ہے۔</p>\n<h2 id=\"quick-reference-checklist\">فوری حوالہ چیک لسٹ</h2>\n<p>صاف ترین اصل اپ لوڈ کریں، سویچ گنتی طے کریں، فیصد اور پٹی پڑھیں، پھر CSS یا JSON کاپی کریں اور پیلیٹ کارڈ ڈاؤن لوڈ کریں۔</p>\n<p>قریب نقل شدہ رنگ ہٹائیں، گم شدہ ایکسنٹ آئی ڈراپر سے بچائیں، اور ٹیب بند کرنے سے پہلے برآمد پراجیکٹ کے ساتھ محفوظ کریں۔</p>\n<p>مکمل پس منظر کے لیے <a href=\"/ur/blog/tasveer-rang-palette-extractor-rehnumai/\">Colour Palette Extractor: Complete Guide</a> پڑھیں، اور ڈیزائن ورک فلو نکات کے لیے <a href=\"/ur/blog/photo-se-rang-palette-design/\">Colour Palettes from Photos: Design Workflow Tips</a> دیکھیں۔</p>\n";

